"""
Btssm Setup
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_factory import BtssmFactory
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class BtssmSetup(object):
    """
    Btssm Setup
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def setup_oamops(self, **kwargs):
        """
        Function to setup oamops
        """
        jars_path = kwargs.get("jars_path", None)
        install_location = kwargs.get("jars_path", None)
        host_ip = kwargs.get("host_ip", "127.0.0.1")
        log_path = kwargs.get("log_path", "/tmp")
        timeout = kwargs.get("timeout", None)
        ne = kwargs.get("ne", "192.168.255.129")
        pw = kwargs.get("pw", "Nemuadmin:nemuuser")
        rc_only = kwargs.get("rc_only", False)
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["jars_path", "install_location", "host_ip", "log_path", "timeout",
                              "ne", "pw", "rc_only"]}
        self.oam_tool.setup_btssm(jars_path, install_location, host_ip, log_path, timeout, ne, pw,
                                  rc_only, **kwargs)

    def teardown_oamops(self, **kwargs):
        """
        Function to teardown oamops
        """
        all_alias = kwargs.get("all_alias", False)
        kwargs = {key: value for key, value in list(kwargs.items()) if key not in ["all_alias"]}
        if all_alias:
            self.oam_tool.teardown_all_aliases_for_btssm()
        else:
            self.oam_tool.teardown_btssm(**kwargs)
